INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N045-01','CN0099','S045-01','分股水量及工艺','2022封面、3.1、4.5.2、表4.5-7至11','1.2万吨混合产品，总投资6000、综合环保600万元非污水专款；项目13223m²，中心118.1649059E/36.7635208N。前三股37018.76m³/a，生产组38369，200m³/d设计物化；生活1200缺氧好氧接触氧化；二级制水RO产水率65%、浓水20421.21并总排口59990，非污水膜。截图失败用正文。','WEB_PRIMARY','公开正文/摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N045-02','CN0099','S045-01','盐负荷冲突','表4.5-11、4.6-2','接管盐164.74t/a，三本账另148.46；SS94.2/94.21舍入异文；沉渣10、制水废RO膜0.1、蒸馏釜残34.67、过滤洗涤渣44.61t/a为固废预测，非水量；全厂预测62028.4含在建微晶蜡2038.4。','WEB_PRIMARY','公开正文/摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N045-03','CN0099','S045-02','正式批复','2025-03-12一、二（一）','32000吨项目现厂南侧，代码2312-370300-89-01-637686；改质4950、两铑系1和49、纳米分子筛3000t/a。高氨提浓；高浓难降解芬顿+一体化生化；合并其他水酸碱中和混凝纳园区。已批非已建，不能与2022图串联。截图失败。','WEB_PRIMARY','公开正文/摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N045-04','CN0130','S045-03','原资料归属纠错','招股书1-1-86/87及合规段','蒸发工艺在（2）江西凯大条目，不是浙江。浙江1200t/a项目2022-04开始生产、2022-03-24许可证、2020-05-28环评；康桥2022-05停产。旧W0068/D024-07/R024-07/A024-07移正至CN0303，浙江站工艺恢复待核。','WEB_COMPANY','公开正文/摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N045-05','CN0303','S045-03','历史工艺','招股书1-1-87','江西上饶广丰青泰路6号；历史反应水蒸发，冷凝回用，残渣危废；生活一体化纳管。原表称正常，非独立监测、非2026现状。','WEB_COMPANY','公开正文/摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N045-06','CN0303','S045-04','股权变更','2026-07-16公告','2026-07-15工商变更完成，股权转让；地址及统一信用代码同一主体，不能据此推断停产或现行产量。','WEB_COMPANY','公开正文/摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N045-07','CN0188','S037-01','历史产量与监测','2.3.1–3，表2-11/12、2-17、总量','康桥路7号，2012审批、2013验收杭环拱验[2013]62，2020登记91330100768244088Q001Y；2020总排口pH7.29、COD25、SS18。表670m³/a、正文约670t/a，保留单位差；COD0.034/氨氮0.003t/a为排放核算。历史环评两项300kg/a与上市问询超批披露并存，不能作完整实产；2022-05公司停产。截图超限。','WEB_PRIMARY','公开正文/摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N045-08','CN0200','S045-05','换领许可分项','2025-12-25核发公示','合计2500t/a，HW50 2246、HW13 2、HW18 50、HW19 100、HW49 102。原2023设计2500废剂与核发混合范围区分；不作实际经营量或污水站运行。未得环评附件水量。','WEB_PRIMARY','公开正文/摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N045-09','CN0129','S045-06','设计无工艺水','淄环审〔2020〕71号第1、2页','氯化钡装置转产2万吨再生，FCC15000、加氢4000、氧化锌1000t/a；总投资11000、环保300万元非污水专款。批复明确无工艺废水、无新增生活水；既有生活化粪池纳齐鲁石化，非全厂零排水。废酸液危废、脱硫石膏另鉴别。截图失败。','WEB_PRIMARY','公开正文/摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N045-10','CN0144','S045-07','一期审批','2026-04-01公告','一期中试审批，不等于二期再生回收获批或投产。','WEB_PRIMARY','公开正文/摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N045-11','CN0144','S045-08','中试工程边界','拟批公示项目行摘录','一期投资2000万元，PX、环己烷脱氢、高效氨化中试；高效氨化催化剂粗品2.15t/a，PX2、苯粗品5.83t/a为应用产品。二期贵金属、分子筛回收不纳；多项目公示的含铅UF/RO蒸发属于邻行，不归神马，未得本项目完整水段。','WEB_PRIMARY','公开正文/摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N045-12','CN0144','S045-09','2025正式批复','平环审〔2025〕8号','3000吨分子筛技改2025-06-20批准，原审批公告已有，本次补正式文件，不重复设计水事实。截图超限。','WEB_PRIMARY','公开正文/摘录，未归档原件','2026-11-28');
